"""Produce a single-file, offline inspection aid; not the Svelte OKF Explorer."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'bundle/okf-bundle.json').read_text())
embedded=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
template=r'''<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>OKF+ | Early-years rehearsal</title>
<style>
:root{font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#152632;background:#f2f5f6;line-height:1.5}*{box-sizing:border-box}body{margin:0}header{background:#153847;color:#fff;padding:28px 5vw 26px}header p{max-width:820px;margin:8px 0 0;color:#d9e6e9}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:.75rem;color:#91d3d3}h1{font-size:clamp(1.65rem,3vw,2.6rem);margin:6px 0;line-height:1.2}.banner{padding:12px 5vw;background:#fff0cf;border-bottom:1px solid #e1ca94;font-size:.92rem}.metrics{display:flex;gap:28px;padding:18px 5vw;background:white;border-bottom:1px solid #d3dce0}.metrics strong{font-size:1.35rem;display:block}.metrics span{font-size:.8rem;color:#526672}main{display:grid;grid-template-columns:300px minmax(0,1fr);gap:24px;max-width:1450px;margin:auto;padding:28px 4vw}aside{background:white;border:1px solid #d3dce0;border-radius:10px;padding:18px;align-self:start}label{display:block;font-size:.84rem;font-weight:650;margin:0 0 6px}input,select{width:100%;padding:11px 10px;border:1px solid #879ca7;border-radius:5px;background:white;font:inherit;margin-bottom:15px}input:focus,select:focus,button:focus-visible,a:focus-visible{outline:3px solid #c29400;outline-offset:3px}button{font:inherit;cursor:pointer}#results{max-height:65vh;overflow:auto;padding:4px}#results button{display:block;text-align:left;width:100%;padding:11px 9px;background:none;border:0;border-left:3px solid transparent;border-radius:3px;margin:3px 0;font-size:.9rem}#results button[aria-current=true]{background:#e6f3f2;border-left-color:#157576}#results button:hover{background:#eef3f5}.small{font-size:.82rem;color:#526672}.panel{background:white;border:1px solid #d3dce0;border-radius:10px;padding:24px;margin-bottom:18px;min-width:0}h2{margin:0 0 8px;font-size:1.5rem}h3{font-size:1.05rem;margin:20px 0 10px}.chip{display:inline-block;font-size:.72rem;background:#e8eff1;border-radius:4px;padding:4px 7px;margin:0 5px 6px 0;font-weight:650}.chip.warn{background:#fff0cf}.description{font-size:1.02rem;max-width:80ch}.relation{display:grid;grid-template-columns:1fr auto 1fr;gap:14px;align-items:center;border:1px solid #cbdde0;background:#f6fbfb;padding:13px;border-radius:7px;margin:10px 0}.relation button{border:0;background:none;text-align:left;padding:0;color:#075966;text-decoration:underline;font-weight:600}.verb{text-align:center;font-size:.79rem;max-width:170px;color:#345b66}.arrow{display:block;font-size:1.5rem;line-height:1}.proof{margin:6px 0 16px;padding:0 12px;font-size:.8rem;color:#526672;overflow-wrap:anywhere}pre{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.83rem;white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f5f6;padding:16px;border-radius:5px}summary{cursor:pointer;font-weight:650;padding:8px 0}#error{color:#a42222}footer{max-width:1350px;margin:0 auto;padding:12px 4vw 40px;font-size:.85rem;color:#526672}a{color:#075966} .toolbar{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:18px}.toolbar select{max-width:310px;margin-bottom:0}.toolbar label{margin:0}code{overflow-wrap:anywhere}.route{font-size:.73rem;overflow-wrap:anywhere;color:#647681;margin-top:14px}@media(max-width:760px){main{grid-template-columns:1fr;padding:18px}#results{max-height:240px}.metrics{gap:20px}.panel{padding:18px}.relation{grid-template-columns:1fr}.verb{max-width:none;text-align:left}.arrow{display:inline-block;transform:rotate(90deg);margin-right:7px}.toolbar{display:block}.toolbar select{max-width:none;margin-top:6px}}
</style></head><body>
<header><div class="eyebrow">Open Knowledge Format · rehearsal 0.1</div><h1>What does this relationship actually mean?</h1><p>Inspect fictional early-years records, candidate links and action states. Follow the evidence without turning a proposal into a fact.</p></header>
<div class="banner"><strong>Synthetic data. No operational authority.</strong> This offline preview is an independent inspection aid, not the canonical Svelte OKF Explorer. No information leaves this page.</div>
<div class="metrics"><div><strong>22</strong><span>concepts</span></div><div><strong>23</strong><span>directed relationships</span></div><div><strong>3</strong><span>candidate links</span></div><div><strong>0</strong><span>identity merges</span></div></div>
<main><aside><label for="search">Find a concept</label><input id="search" type="search" placeholder="Try H-01, proposed or no-contact"><label for="type">Concept type</label><select id="type"><option value="">All types</option></select><p id="count" class="small" role="status"></p><nav id="results" aria-label="Concepts"></nav></aside>
<section aria-label="Selected concept"><div class="toolbar"><div><label for="mode">Representation</label><select id="mode"><option value="typed">OKF+ — typed relationships</option><option value="plain">Plain OKF — the same facts in prose</option></select></div><span class="small">Local, source-bound inspection</span></div>
<div class="panel"><div id="chips"></div><h2 id="title" tabindex="-1"></h2><p id="description" class="description"></p><div id="facts"></div><p id="route" class="route"></p></div>
<div class="panel" id="relationships-panel"><h2>Directed relationships</h2><p class="small">Read left to right. Reverse navigation does not create a second fact. A candidate link is a proposal about records, not an assertion that people are identical.</p><div id="relationships"></div></div>
<div class="panel"><h2>Source evidence</h2><div id="evidence"></div><details><summary>Read the full Markdown body</summary><pre id="body"></pre></details></div><p id="error" role="alert"></p>
</section></main><footer>The example.invalid identifiers are deliberately non-live. Source files, locators and SHA-256 hashes refer to the accompanying kit. The fixture dates are fixed for reproducibility, not a claim of human review. <strong>Do not use this demo to make a decision about a child.</strong></footer>
<script>
'use strict';
const DATA=__DATA__;
const corpus=DATA.corpora['ey-rehearsal']; const nodes=corpus.nodes;const relationships=corpus.relationships;
const $=id=>document.getElementById(id);let selected='candidate/c-01';
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function list(){const q=$('search').value.toLowerCase();const type=$('type').value;let count=0;$('results').replaceChildren();
for(const [route,node] of Object.entries(nodes)){if(type&&node.type!==type)continue;if(q&&!JSON.stringify(node).toLowerCase().includes(q))continue;count++;const b=el('button',node.title);b.dataset.route=route;b.setAttribute('aria-current',String(route===selected));b.onclick=()=>choose(route,true);$('results').append(b);}
$('count').textContent=count+' of '+Object.keys(nodes).length+' concepts';}
function choose(route,focus=false){if(!nodes[route]){$('error').textContent='The requested concept is not present in this snapshot.';return;}selected=route;location.hash=encodeURIComponent(route);const n=nodes[route];$('error').textContent='';$('title').textContent=n.title;$('description').textContent=n.description;$('route').textContent='Route: '+route+' · Entity: '+n.semantic_id;
$('chips').replaceChildren(el('span',n.type,'chip'),el('span','SYNTHETIC','chip warn'),el('span','UNVERIFIED PROTOTYPE','chip warn'));
$('facts').replaceChildren(el('h3','Source-native facts'),el('pre',JSON.stringify(n.facts,null,2)));$('body').textContent=n.body;
$('evidence').replaceChildren();for(const e of n.sources){$('evidence').append(el('pre','File: '+e.source_artifact+'\nLocator: '+e.locator+'\nSHA-256: '+e.source_sha256+'\nURL status: '+e.url_status));}
$('relationships').replaceChildren();const rels=relationships.filter(r=>r.source===route||r.target===route);
for(const r of rels){const card=el('div',undefined,'relation');const source=el('button',nodes[r.source].title);source.onclick=()=>choose(r.source,true);const target=el('button',nodes[r.target].title);target.onclick=()=>choose(r.target,true);const verb=el('div',r.label,'verb');verb.append(el('span','→','arrow'));card.append(source,verb,target);const proof=el('details',undefined,'proof');proof.append(el('summary','Inspect predicate and provenance'),el('pre',JSON.stringify(r,null,2)));$('relationships').append(card,proof);}
if(!rels.length)$('relationships').append(el('p','No incoming or outgoing directed relationships in this snapshot.'));
$('relationships-panel').hidden=$('mode').value==='plain';list();if(focus)$('title').focus();}
for(const type of [...new Set(Object.values(nodes).map(n=>n.type))].sort()){$('type').append(new Option(type,type));}
$('search').oninput=list;$('type').onchange=list;$('mode').onchange=()=>choose(selected);
window.onhashchange=()=>{const r=decodeURIComponent(location.hash.slice(1));if(r!==selected)choose(r);};
const initial=decodeURIComponent(location.hash.slice(1));choose(initial||selected);
</script></body></html>'''
(ROOT/'preview/index.html').write_text(template.replace('__DATA__',embedded),encoding='utf-8')
print('Built self-contained offline preview')
